def check_m(m):
    if m % 3 == 1:
        return False # T is not an integer

    T = m * (m + 1) // 6
    S = list(range(1, m + 1))

    # For m=8, T=12. Test X={1, 2, 3, 6}, Y={4, 8}
    if m == 8:
        X = [1, 2, 3, 6]
        Y = [4, 8]
        if sum(X) == T and sum(Y) == T and not set(X).intersection(set(Y)):
            return True
        return False

    # For m=9, T=15. Test X={1, 2, 3, 4, 5}, Y={6, 9}
    if m == 9:
        X = [1, 2, 3, 4, 5]
        Y = [6, 9]
        if sum(X) == T and sum(Y) == T and not set(X).intersection(set(Y)):
